<?php
function form_html(string $title,string $content):string{return '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'.h($title).' · Rundfunkbeitrag Support</title><link rel="stylesheet" href="/admin-login.css"><link rel="icon" href="/favicon.svg"></head><body><main><a class="brand" href="/"><img src="/brand/antenna.svg" width="48" height="48" alt=""><span>Rundfunkbeitrag<strong>Support <i class="black"></i><i class="red"></i><i class="gold"></i></strong></span></a><h1>'.h($title).'</h1>'.$content.'<footer>Wir sind nicht mit ARD, ZDF, Deutschlandradio oder Beitragsservice verbunden.</footer></main></body></html>';}
function login_page(string $error=''):never{header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store');echo form_html('Administrator',($error?'<p class="error" role="alert">'.h($error).'</p>':'').'<form method="post" action="/api/admin/login"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><label>E-Mail<input name="email" type="email" autocomplete="username" required></label><label>Passwort<input name="password" type="password" autocomplete="current-password" required maxlength="256"></label><button>Anmelden</button></form>');exit;}
function auth_route(string $path,string $method):bool{
 if($path==='/admin/settings-transfer'){
 // Copy the start settings between two installations (e.g. Hostinger -> OVH): export here, paste on the other site. Real orders stay off after an import; the Resend key is never shown.
 if(!admin()){header('Location: /admin/login',true,303);exit;}$error='';$done='';
 if($method==='POST'){try{csrf();$in=json_decode((string)($_POST['data']??''),true);if(!is_array($in)||!is_array($in['settings']??null))fail('INVALID_TRANSFER_DATA');$s=record('settings:service',true)['value']??rules()['emptySettings'];$next=rules()['emptySettings'];foreach($next as $key=>$v)if(!in_array($key,['version','liveEnabled'],true))$next[$key]=text((string)($in['settings'][$key]??''),0,30000);$next['iban']=strtoupper(preg_replace('/\s/','',$next['iban']));$next['version']=$s['version']+1;$next['liveEnabled']=false;put('settings:service','settings',$next);$from=text((string)($in['email_from']??''),0,250);$address=preg_match('/<([^<>]+)>$/',$from,$m)?$m[1]:$from;if($from!==''&&!preg_match('/[\r\n]/',$from)&&filter_var($address,FILTER_VALIDATE_EMAIL)&&empty(config()['email_from'])){$c=config();$c['email_from']=$from;$tmp=tempnam(private_root(),'.config-');chmod($tmp,0600);file_put_contents($tmp,"<?php\nreturn ".var_export($c,true).";\n",LOCK_EX);if(!rename($tmp,private_root().'/config.php'))fail('CONFIG_WRITE_FAILED',503);if(function_exists('opcache_invalidate'))opcache_invalidate(private_root().'/config.php',true);}$done='Übernommen. Echte Bestellungen bleiben ausgeschaltet. / Imported. Real orders stay switched off.';}catch(AppError $e){$error=$e->reason;}}
 $s=settings();unset($s['version'],$s['liveEnabled']);$export=json_encode(['settings'=>$s,'email_from'=>config()['email_from']??''],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);
 header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store');
 echo form_html('Einstellungen übertragen',($error?'<p class="error">'.h($error).'</p>':'').($done?'<p>'.h($done).'</p>':'').'<p>Export dieser Website (kopieren und auf der anderen Website einfügen). / Export of this site.</p><label><textarea readonly rows="12" onclick="this.select()">'.h($export).'</textarea></label><form method="post"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><label>Import (überschreibt die Starteinstellungen dieser Website) / Import<textarea name="data" rows="8" required></textarea></label><button>Importieren / Import</button></form><p><a href="/admin">Zum Verwaltungsbereich / Back to administration</a></p>');exit;
 }
 if($path==='/admin/configuration'){
 if(!admin()){header('Location: /admin/login',true,303);exit;}$c=config();$error='';
 if($method==='POST'){try{csrf();$key=text($_POST['resend_key']??'',0,256);if($key!==''&&!preg_match('/^re_[A-Za-z0-9_-]+$/',$key))fail('INVALID_EMAIL_KEY');$from=text($_POST['email_from']??'',0,250);if(preg_match('/[\r\n]/',$from))fail('INVALID_EMAIL');$address=preg_match('/<([^<>]+)>$/',$from,$m)?$m[1]:$from;if($from!==''&&!filter_var($address,FILTER_VALIDATE_EMAIL))fail('INVALID_EMAIL');if($key!=='')$c['resend_key']=$key;$c['email_from']=$from;$c['indexing']=isset($_POST['indexing']);$tmp=tempnam(private_root(),'.config-');chmod($tmp,0600);file_put_contents($tmp,"<?php\nreturn ".var_export($c,true).";\n",LOCK_EX);if(!rename($tmp,private_root().'/config.php'))fail('CONFIG_WRITE_FAILED',503);if(function_exists('opcache_invalidate'))opcache_invalidate(private_root().'/config.php',true);header('Location: /admin/configuration',true,303);exit;}catch(AppError $e){$error=$e->reason;}}
 echo form_html('E-Mail & Einstellungen',($error?'<p class="error">'.h($error).'</p>':'').'<p>'.(!empty($c['resend_key'])?'API-Schlüssel gespeichert. / API key saved.':'E-Mail-Versand noch nicht eingerichtet. / Email is not configured.').'</p><form method="post"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><label>Resend API key<input type="password" name="resend_key" autocomplete="new-password" placeholder="Leave empty to keep the existing key"></label><label>Verified sender<input name="email_from" value="'.h($c['email_from']).'" maxlength="250"></label><label><input type="checkbox" name="indexing" '.($c['indexing']?'checked':'').'> Search-engine indexing after launch</label><button>Speichern / Save</button></form><p><a href="/admin">Zum Verwaltungsbereich / Back to administration</a></p>');exit;
 }
 if($path==='/admin/login'){if($method!=='GET')fail('METHOD_NOT_ALLOWED',405);login_page();}
 if($path==='/api/admin/login'){if($method!=='POST')fail('METHOD_NOT_ALLOWED',405);csrf();db()->beginTransaction();rate('admin-login:'.($_SERVER['REMOTE_ADDR']??''),15,900);db()->commit();if(!is_string($_POST['password']??null)||strlen($_POST['password'])>72||!password_verify($_POST['password'],config()['admin_hash'])||!is_string($_POST['email']??null)||strtolower(trim($_POST['email']))!==config()['admin_email']){http_response_code(401);login_page('E-Mail oder Passwort ist nicht korrekt.');}session_regenerate_id(true);$_SESSION['admin_until']=time()+28800;$_SESSION['admin_fingerprint']=secret_hash(config()['admin_hash']);$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /admin',true,303);exit;}
 if($path==='/api/admin/logout'){if($method!=='POST')fail('METHOD_NOT_ALLOWED',405);csrf();unset($_SESSION['admin_until'],$_SESSION['admin_fingerprint']);session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /admin/login',true,303);exit;}
 return false;
}
function admin_password(mixed $value):string{text($value,14,72);if(strlen($value)>72)fail('PASSWORD_MAX_72_BYTES');return $value;}
function installer():never{
 if(is_file(private_root().'/config.php')){http_response_code(404);exit;}
 $keyFile=private_root().'/installation-key.php';if(!is_file($keyFile)){http_response_code(503);echo form_html('Installation','<p>Prepare the private installation key using the supplied instructions.</p>');exit;}
 $secret=require $keyFile;if(!is_string($secret)||strlen($secret)<24||$secret==='CHOOSE_AT_LEAST_24_RANDOM_CHARACTERS'){http_response_code(503);echo form_html('Installation','<p>Set your own private installation key first.</p>');exit;}
 $secure=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');$host=$_SERVER['HTTP_HOST']??'';$local=preg_match('/^(localhost|127\.0\.0\.1)(:\d+)?$/',$host);if(!$secure&&!$local){http_response_code(403);echo form_html('Installation','<p>Open the installer using HTTPS.</p>');exit;}
 $dir=private_root().'/data';foreach(['sessions','uploads','tmp','fonts'] as $part)if(!is_dir($dir.'/'.$part))mkdir($dir.'/'.$part,0700,true);session_save_path($dir.'/sessions');session_name($secure?'__Host-rb-session':'rb-session-local');session_set_cookie_params(['path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Strict']);ini_set('session.use_strict_mode','1');session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));$error='';
 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??'')||($_SERVER['HTTP_ORIGIN']??'')!==($secure?'https://':'http://').$host)fail('SAME_ORIGIN_REQUIRED',403);
 $attemptFile=$dir.'/installer-attempts.json';$lock=fopen($dir.'/installer.lock','c+');if(!$lock||!flock($lock,LOCK_EX))fail('INSTALLATION_BUSY',503);if(is_file(private_root().'/config.php'))fail('ALREADY_INSTALLED',409);$attempts=is_file($attemptFile)?json_decode(file_get_contents($attemptFile),true):['count'=>0,'until'=>time()+900];if($attempts['until']<time())$attempts=['count'=>0,'until'=>time()+900];if(++$attempts['count']>15)fail('RATE_LIMITED',429);file_put_contents($attemptFile,json_encode($attempts),LOCK_EX);chmod($attemptFile,0600);if(!hash_equals($secret,$_POST['installation_key']??''))fail('INVALID_INSTALLATION_KEY',403);
 $url=rtrim(text($_POST['public_url']??null,8,250),'/');$expected=($secure?'https://':'http://').$host;if($url!==$expected)fail('PUBLIC_URL_MUST_MATCH_THIS_SITE');$dbHost=text($_POST['db_host']??'localhost');$dbName=text($_POST['db_name']??null);if(!preg_match('/^[A-Za-z0-9._-]+$/',$dbHost)||!preg_match('/^[A-Za-z0-9_]+$/',$dbName))fail('INVALID_DATABASE_DETAILS');$c=['public_url'=>$url,'db_dsn'=>'mysql:host='.$dbHost.';dbname='.$dbName.';charset=utf8mb4','db_user'=>text($_POST['db_user']??null,1,150),'db_password'=>text($_POST['db_password']??null,1,256),'admin_email'=>email($_POST['admin_email']??null),'admin_hash'=>password_hash(admin_password($_POST['admin_password']??null),PASSWORD_DEFAULT),'app_secret'=>bin2hex(random_bytes(32)),'resend_key'=>text($_POST['resend_key']??'',0,256),'email_from'=>text($_POST['email_from']??'',0,250),'indexing'=>false];
 $pdo=new PDO($c['db_dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec(file_get_contents(__DIR__.'/schema.sql'));$stmt=$pdo->prepare('INSERT IGNORE INTO rb_records(id,kind,parent_id,owner_hash,data_json,version,created_at,updated_at) VALUES (?,?,\'\',\'\',?,1,?,?)');$stmt->execute(['counter:invoice','counter','{"value":0}',time(),time()]);$stmt->execute(['settings:service','settings',json_encode(rules()['emptySettings'],JSON_UNESCAPED_UNICODE),time(),time()]);
 $content="<?php\n// Private configuration. Never commit or expose this file.\nreturn ".var_export($c,true).";\n";$file=fopen(private_root().'/config.php','x');if(!$file)fail('CONFIG_WRITE_FAILED',503);chmod(private_root().'/config.php',0600);if(fwrite($file,$content)!==strlen($content)){fclose($file);unlink(private_root().'/config.php');fail('CONFIG_WRITE_FAILED',503);}fclose($file);unlink($keyFile);flock($lock,LOCK_UN);fclose($lock);session_regenerate_id(true);$_SESSION=[];header('Location: /admin/login',true,303);exit;
 }catch(Throwable $e){if(isset($lock)&&is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}$error=$e instanceof AppError?$e->reason:'Database or folder configuration could not be completed. Check your details.';error_log('Installer: '.($e instanceof AppError?$e->reason:'Database/setup error'));}
 }
 $fields=['installation_key'=>['Diegimo raktas','password',''],'public_url'=>['Svetainės adresas','url',($secure?'https://':'http://').$host],'db_host'=>['MySQL serveris','text','localhost'],'db_name'=>['Duomenų bazės pavadinimas','text',''],'db_user'=>['Duomenų bazės vartotojas','text',''],'db_password'=>['Duomenų bazės slaptažodis','password',''],'admin_email'=>['Administratoriaus el. paštas','email',''],'admin_password'=>['Administratoriaus slaptažodis (14+ simbolių, iki 72 baitų)','password',''],'resend_key'=>['Resend API raktas (galima papildyti vėliau)','password',''],'email_from'=>['Laiškų siuntėjas (galima papildyti vėliau)','text','']];$html='<p>PHP svetainės pirmasis paleidimas. MySQL duomenis rasite Hostinger skydelyje.</p>'.($error?'<p class="error">'.h($error).'</p>':'').'<form method="post"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';foreach($fields as $name=>[$label,$type,$value])$html.='<label>'.h($label).'<input name="'.$name.'" type="'.$type.'" value="'.h($value).'" '.(!in_array($name,['resend_key','email_from'],true)?'required':'').' autocomplete="'.($type==='password'?'new-password':'off').'"></label>';$html.='<button>Paruošti svetainę</button></form>';echo form_html('Pirmasis paleidimas',$html);exit;
}
